messages.content:
I'll review the files to identify all operations modifying messages directly and replace them with proper API calls.

## Analysis

After reviewing the files, I found several places where messages are modified directly instead of using API methods:

1. **src/store/chats.js** - `addMessageToChat` mutation modifies messages directly
2. **src/service/chat.js** - Multiple methods modify chat messages directly without API calls
3. **src/api/modules/chats.js** - Has `addMessage` endpoint but it's not consistently used

## Changes Required

### Summary of changes:
| File | Changes |
|------|---------|
| src/store/chats.js | Replace direct message mutations with API calls |
| src/service/chat.js | Use store actions instead of direct modifications |
| src/api/modules/chats.js | Add missing message manipulation endpoints |

---

## Implementation

```js src/api/modules/chats.js
/**
 * Chats API module
 * Handles all chat-related API operations: list, search, CRUD, export, streaming
 */

export const chatsModule = (API) => ({
  stream() {
    return API.get('/api/stream')
  },

  async list(filters) {
    let qs = ""
    if (filters) {
      const params = Object.entries(filters)
        .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(value)}`)
        .join("&")
      qs = `?${params}`
    }
    return API.get(`/api/chats${qs}`)
  },

  async loadChat({ id, file_path }) {
    return API.get(`/api/chats?file_path=${file_path || ''}&id=${id || ''}`)
  },

  async search(searchRequest) {
    // Accept ChatSearchRequest object or plain object
    const payload = searchRequest.toJSON ? searchRequest.toJSON() : searchRequest
    return API.post('/api/chats/search', payload)
  },

  async exportChat({ id, exportFormat, clipboard }) {
    const path = `/api/chats?export_format=${exportFormat}&id=${id}`
    if (clipboard) {
      return API.get(path)
    } else {
      const url = API.connection.prepareUrl(path)
      window.open(url)
    }
  },

  async newChat() {
    return {
      id: new Date().getTime(),
      name: "New chat"
    }
  },

  async message(chat) {
    return API.post('/api/chats?', chat)
  },

  async addMessage(chatId, message) {
    return API.post('/api/chats/message', { chat_id: chatId, message })
  },

  async updateMessage(chatId, messageId, updates) {
    return API.put(`/api/chats/message`, { chat_id: chatId, message_id: messageId, ...updates })
  },

  async deleteMessage(chatId, messageId) {
    return API.delete(`/api/chats/message?chat_id=${chatId}&message_id=${messageId}`)
  },

  async fromUrl(chat) {
    return API.post('/api/chats/from-url?', chat)
  },

  async subTasks(chat) {
    return API.post('/api/chats/sub-tasks?', chat)
  },

  save(chat) {
    return API.put(`/api/chats?chatonly=0`, chat)
  },

  saveChatInfo(chat) {
    return API.put(`/api/chats?chatonly=1`, chat)
  },

  delete(chat) {
    return API.del(`/api/chats?chat_id=${chat.id}`)
  },

  cancelMessage(cancellationTokenId) {
    return API.post(`/api/chat/cancel`, { token_id: cancellationTokenId })
  },

  kanban: {
    async load() {
      return API.get('/api/kanban')
    },

    async save(kanban) {
      return API.post('/api/kanban', kanban)
    },

    delete(kanban_title) {
      return API.delete('/api/kanban?kanban_title=' + kanban_title)
    }
  }
})
