/**
 * Chats API module
 * Handles all chat-related API operations: list, search, CRUD, export, streaming
 */

export const chatsModule = (API) => ({
  stream() {
    return API.get('/api/stream')
  },

  async list(filters) {
    let qs = ""
    if (filters) {
      const params = Object.entries(filters)
        .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(value)}`)
        .join("&")
      qs = `?${params}`
    }
    return API.get(`/api/chats${qs}`)
  },

  async loadChat({ id, file_path }) {
    return API.get(`/api/chats?file_path=${file_path || ''}&id=${id || ''}`)
  },

  async search(searchRequest) {
    // Accept ChatSearchRequest object or plain object
    const payload = searchRequest.toJSON ? searchRequest.toJSON() : searchRequest
    return API.post('/api/chats/search', payload)
  },

  async exportChat({ id, exportFormat, clipboard }) {
    const path = `/api/chats?export_format=${exportFormat}&id=${id}`
    if (clipboard) {
      return API.get(path)
    } else {
      const url = API.connection.prepareUrl(path)
      window.open(url)
    }
  },

  async newChat() {
    return {
      id: new Date().getTime(),
      name: "New chat"
    }
  },

  async message(chat) {
    return API.post('/api/chats', chat)
  },

  async addMessage(chatId, message) {
    return API.post('/api/chats/message', { chat_id: chatId, message })
  },

  async updateMessage(chatId, message) {
    return API.put('/api/chats/message', { chat_id: chatId, message })
  },

  async removeMessage(chatId, messageDocId) {
    return API.delete(`/api/chats/message?chat_id=${chatId}&message_doc_id=${messageDocId}`)
  },

  async updateMessageField(chatId, messageDocId, fieldUpdates) {
    return API.put('/api/chats/message/field', { 
      chat_id: chatId, 
      message_doc_id: messageDocId,
      ...fieldUpdates 
    })
  },

  async updateMetadata(chatId, metadata) {
    return API.post('/api/chats/metadata', { chat_id: chatId, metadata })
  },

  async fromUrl(chat) {
    return API.post('/api/chats/from-url', chat)
  },

  async subTasks(chat) {
    return API.post('/api/chats/sub-tasks', chat)
  },

  save(chat) {
    return API.put(`/api/chats?chat_only=0`, chat)
  },

  saveChatInfo(chat) {
    return API.put(`/api/chats?chat_only=1`, chat)
  },

  delete(chat) {
    return API.delete(`/api/chats?chat_id=${chat.id}`)
  },

  cancelMessage(cancellationTokenId) {
    return API.post(`/api/chat/cancel`, { token_id: cancellationTokenId })
  },

  kanban: {
    async load() {
      return API.get('/api/kanban')
    },

    async save(kanban) {
      return API.post('/api/kanban', kanban)
    },

    delete(kanban_title) {
      return API.delete('/api/kanban?kanban_title=' + kanban_title)
    }
  }
})

import moment from 'moment'
import Service from "./service"
import { extractCodeBlocks, hasCodeBlocksWithPaths } from '../utils/codeBlockExtractor'

export class ChatService extends Service {
  getUserMessage({ message, files, profiles, images, metadata, user, taskItem, task_item }) {
    return {
      role: "user",
      content: message,
      images: images?.map(JSON.stringify) || [],
      files,
      profiles,
      task_item: taskItem,
      user: user || this.$user.username,
      meta_data: metadata,
      done: true,
      task_item,
    }
  }

  async sendMessage({ chat, message }) {
    this.addMessage({ chat, message })
    return this.$projects.chatWihProject(chat)
  }

  async findChat({ id, owner_project_id } = {}) {
    return id
      ? await this.$chats.findProjectChat({ id, owner_project_id })
      : null
  }

  getMessageProfiles({ messageMentions, selectedUser, currentUser }) {
    const profiles = messageMentions
      .filter((m) => m.profile)
      .map((m) => m.profile.name)
    if (selectedUser?.name && selectedUser !== currentUser) {
      profiles.push(selectedUser.name)
    }
    return profiles.filter(
      (v, ix, arr) => arr.findIndex((vv) => vv === v) === ix
    )
  }

  getMessageFiles({ messageMentions, files }) {
    return [... new Set([
      ...messageMentions.filter((m) => m.file).map((m) => m.file),
      ...(files || []),
    ])]
  }

  async addMessage({ chat, message }) {
    if (chat?.id) {
      return await this.$storex.chats.addMessage({ chat, message })
    } else {
      chat.messages = [...(chat.messages || []), message]
    }
  }

  async removeMessage({ chat, message }) {
    if (!chat?.id || !message?.doc_id) {
      return
    }

    const ix = chat.messages.findIndex((m) => m.doc_id === message.doc_id)

    if (chat.mode === "task" && message.role === "assistant" && ix > 1) {
      chat.messages[ix - 1].hide = false
      if (chat.messages[ix - 2]) chat.messages[ix - 2].hide = false
    }

    return await this.$storex.chats.removeMessage({ chat, messageDocId: message.doc_id })
  }

  async toggleHide({ chat, doc_id }) {
    if (!chat?.id || !doc_id) {
      return
    }

    const msg = chat.messages.find((m) => m.doc_id === doc_id)
    if (!msg) return

    const newHideValue = !msg.hide
    return await this.$storex.chats.updateMessage({ 
      chat, 
      messageDocId: doc_id,
      fieldUpdates: { hide: newHideValue }
    })
  }

  async toggleAnswer({ chat, doc_id }) {
    if (!chat?.id || !doc_id) {
      return
    }

    const msg = chat.messages.find((m) => m.doc_id === doc_id)
    if (!msg) return

    const newAnswerValue = !msg.is_answer
    return await this.$storex.chats.updateMessage({ 
      chat, 
      messageDocId: doc_id,
      fieldUpdates: { is_answer: newAnswerValue }
    })
  }

  async hideAll({ chat }) {
    if (!chat?.id || !chat.messages?.length) {
      return
    }

    const hideUpdates = chat.messages.map(m => ({
      doc_id: m.doc_id,
      hide: true
    }))

    return await this.$storex.chats.updateMessages({ 
      chat, 
      messages: hideUpdates 
    })
  }

  async updateExistingMessage({ chat, doc_id, update }) {
    if (!chat?.id || !doc_id) {
      return
    }

    return await this.$storex.chats.updateMessage({ 
      chat, 
      messageDocId: doc_id,
      fieldUpdates: update
    })
  }

  async removeFileFromMessage({ message, file }) {
    if (!message || !file) return
    message.files = message.files.filter((f) => f !== file)
  }

  async removeFileFromChat({ chat, file }) {
    if (!chat?.id || !file) return
    const updatedFileList = chat.file_list?.filter((f) => f !== file) || []
    return await this.$storex.chats.updateChatInfo({ 
      chat, 
      updates: { file_list: updatedFileList }
    })
  }

  async addFileToChat({ chat, file }) {
    if (!chat?.id || !file) return false
    if (chat.file_list?.includes(file)) return false

    const updatedFileList = [...(chat.file_list || []), file]
    await this.$storex.chats.updateChatInfo({ 
      chat, 
      updates: { file_list: updatedFileList }
    })
    return true
  }

  async parseImageFromPaste(e) {
    if (!e.clipboardData?.items) return null
    return (
      [...e.clipboardData.items]
        .find((f) => f.type.indexOf("image") !== -1)
        ?.getAsFile() || null
    )
  }

  async parseTextFromPaste(e) {
    if (!e.clipboardData?.items) return null
    const textItem = [...e.clipboardData.items].find(
      (f) => f.type.indexOf("text") !== -1
    )
    if (!textItem) return null
    return new Promise((ok) => textItem.getAsString(ok))
  }

  extractImageUrlFromHtml(html) {
    if (!html.startsWith("<img")) return null
    const match = /src="([^"]+)/.exec(html)
    return match ? match[1] : null
  }

  async uploadImage({ file }) {
    const formData = new FormData()
    formData.append("file", file)
    const response = await this.$storex.api.images.upload(formData)
    return response.path
  }

  async fileToMessage({ file }) {
    const content = await this.$storex.api.files.read(file)
    const ext = file.split(".").reverse()[0]
    return ["```" + `${ext} ${file}`, content, "```"].join("\n")
  }

  async extractTextFromImage(image) {
    const byteString = atob(image.src.split(",")[1])
    const mimeString = image.src.split(",")[0].split(":")[1].split(";")[0]
    const byteArray = new Uint8Array(byteString.length)
    for (let i = 0; i < byteString.length; i++)
      byteArray[i] = byteString.charCodeAt(i)
    const blob = new Blob([byteArray], { type: mimeString })
    const file = new File([blob], "image", { type: mimeString })
    return this.$api.tools.imageToText(file)
  }

  buildSubTaskPayload({
    title,
    description,
    files,
    profiles,
    mode,
    column,
    projectId,
    parentId,
    board,
    metadata,
    user,
  }) {
    return {
      name: title,
      messages: [
        {
          role: "user",
          content: description,
          images: [],
          profiles: [],
          user: user || this.$user.username,
          meta_data: {},
          done: true,
        },
      ],
      project_id: projectId,
      parent_id: parentId,
      file_list: files || [],
      profiles: profiles || [],
      mode: mode,
      column: column,
      board: board,
      metadata: metadata || {},
      activateChat: false,
    }
  }

  getCaretWordInfo(editor) {
    if (!editor?.innerText) return {}
    const caretIndex = this._getEditorCaretCharOffset(editor)
    const text = editor.innerText
    const lastWorkIndex = text.slice(0, caretIndex).split(/\s/g).length - 1
    const word = text.split(/\s/g)[lastWorkIndex]
    return { caretIndex, lastWorkIndex, word }
  }

  _getEditorCaretCharOffset(element) {
    let caretOffset = 0
    if (window.getSelection) {
      const range = window.getSelection().getRangeAt(0)
      const preCaretRange = range.cloneRange()
      preCaretRange.selectNodeContents(element)
      preCaretRange.setEnd(range.endContainer, range.endOffset)
      caretOffset = preCaretRange.toString().length
    }
    return caretOffset
  }

  startVoiceRecognition({ lang, onResult, onEnd }) {
    const recognition = new (window.SpeechRecognition ||
      window.webkitSpeechRecognition)()
    recognition.lang = lang
    recognition.interimResults = false
    recognition.onresult = onResult
    recognition.onend = onEnd
    recognition.start()
    return recognition
  }

  async syncNotebook({ project, chat }) {
    return this.$storex.chat.syncNotebookToChat({ project, chat })
  }

  async exportNotebook({ project, chat, file }) {
    return this.$storex.chat.exportChatToNotebook({ project, chat, file })
  }

  async saveChat(chat) {
    if (!chat.temp) {
      return await this.$chats.saveChat(chat)
    }
  }
  async saveChatInfo(chat) {
    if (!chat.temp) {
      return await this.$chats.saveChatInfo(chat)
    }
  }

  async sendChatMessage({ chat, storex }) {
    return await storex.projects.chatWihProject(chat)
  }

  async validateFile({ file, parentChat }) {
    const fileChat = file.chat || await this.createFileChat({ file, parentChat })

    if (fileChat.messages.some(m => !m.hide)) {
      await this.hideAll({ chat: fileChat })
      await this.saveChat(fileChat)
    }

    const message = this.getUserMessage({
      taskItem: 'review',
      message:
        [
          `Follow profiles instructions to validate the latest changes in the file: ${file.fileFullName}.`,
          "If no profiles are present, create a summary of best practices of the file with example and suggestions of how to improve file quality",
          file.diff ? 'Focus on the last changes from the diff:\n' + file.diff : ''
        ].join("\n"),
      files: [file.fileFullName]
    })

    return this.sendMessage({ chat: fileChat, message })
  }

  async validateAllFiles({ prReviewChat, files }) {
    await Promise.all(
      files.filter((f) => !f.isDeleted).map((file) =>
        this.validateFile({
          file,
          parentChat: prReviewChat,
        })
      )
    )
  }

  async createFileChat({ parentChat, file, project_id, column, message, metadata }) {
    column = column || parentChat.column
    const { fileFullName, fileShortName, profiles } = file
    const payload = this.buildSubTaskPayload({
      title: fileShortName,
      description: message,
      files: [fileFullName],
      profiles: profiles.map(p => p.name),
      mode: 'task',
      column,
      metadata,
      project_id: parentChat.project_id,
      parent_id: parentChat.id,
      board: parentChat.board,
      projectId: project_id || parentChat.project_id,
      parentId: parentChat.id,
      user: this.$user.username
    })
    file.chat = await this.$chats.createNewChat(payload)
    return file.chat
  }

  async newQuickChat(project) {
    const chat = {
      name: "Quick chat",
      mode: 'chat',
      auto_initialize: true
    }
    const quickChat = await this.$chats.createNewChatWithProject({ project, chat })
    this.$storex.ui.showApp({
        key: 'chat',
        name: 'Chat',
        component: 'chat',
        params: {
          chat: quickChat
        }
      })
  }

  async createChat({
    files,
    name,
    mode = 'chat',
    message,
    profiles = [],
    metadata = {},
    activate = false,
  }) {
    const fileNames = (files || []).map(f => f.split('/').pop())
    const chatName = name ||
      `Files: ${fileNames.slice(0, 2).join(', ')}${fileNames.length > 2 ? ` +${fileNames.length - 2}` : ''}`

    const openingMessage = message ||
      `Working with files:\n${(files || []).map(f => `- ${f}`).join('\n')}`

    const payload = {
      name: chatName,
      mode,
      file_list: files || [],
      profiles,
      metadata,
      auto_initialize: false,
      messages: [
        this.getUserMessage({
          message: openingMessage,
          files: files || [],
          profiles,
          metadata,
        })
      ]
    }

    const chat = await this.$chats.createNewChat(payload)

    if (activate) {
      await this.$chats.setActiveChat(chat)
    }

    return chat
  }

  // Get chat project from chat object or fallback to current project
  getChatProject(chat) {
    const projectId = chat?.project_id || chat?.owner_project_id
    if (projectId) {
      return this.$projects.allProjectsById[projectId] || this.$project
    }
    return this.$project
  }

  // Update chat branch metadata
  updateChatBranches({ chat, currentBranch, compareBranch }) {
    if (!chat) return
    chat.meta_data = {
      ...(chat.meta_data || {}),
      current_branch: currentBranch,
      compare_branch: compareBranch
    }
  }

  findChildChatByFile({ chat, childrenChats, file }) {
    const searchNode = (node, visited = new Set()) => {
      if (!node || visited.has(node.id)) return null
      visited.add(node.id)
      if (node.file_list?.includes(file) && node.id !== chat?.id) return node
      if (node.children && Array.isArray(node.children)) {
        for (const child of node.children) {
          const found = searchNode(child, visited)
          if (found) return found
        }
      }
      return null
    }

    if (childrenChats && Array.isArray(childrenChats)) {
      for (const child of childrenChats) {
        const found = searchNode(child)
        if (found) return found
      }
    }

    if (chat) {
      return searchNode(chat)
    }
    return null
  }

  findChatByFileAndMessage({ chat, file, messageId }) {
    if (!file) return null
    const chats = this.$projects?.allChats || []

    // 1. Find directly-linked chat by file and messageId
    let found = chats.find(c => 
      c.file_list?.includes(file) && 
      (c.message_id === messageId || (messageId && c.metadata?.message_id === messageId))
    )
    if (found) return found

    // 2. Fallback to any child chat of parent chat that matches this file
    if (chat) {
      found = chats.find(c => 
        c.file_list?.includes(file) && 
        (c.parent_id === chat.id || c.metadata?.parent_id === chat.id)
      )
    }
    return found || null
  }

  // Add these methods to the ChatService class
  extractCodeBlocksFromMessage(message) {
    return extractCodeBlocks(message?.content || '')
  }

  hasCodeBlocksWithFilePaths(message) {
    return hasCodeBlocksWithPaths(message?.content || '')
  }
}

import { getterTree, mutationTree, actionTree } from 'typed-vuex'
import store, { $storex } from '.'
import { v4 as uuidv4 } from 'uuid'
import { ChatSearchRequest } from '@/api/model/ChatSearchRequest'
import { CHAT_STATUS } from './chatStatuses'

export const namespaced = true

export const state = () => ({
  chats: {},
  activeChatId: null,
  chatEvents: {},
  searchResults: null,
})

function registerChat(state, chat) {
  if (!chat?.id) {
    console.error('[chats store] Attempted to store a null/invalid chat:', chat)
    return
  }
  const existingChat = state.chats[chat.id] || {}
  state.chats[chat.id] = {
    ...existingChat,
    ...chat,
    status: chat.status || CHAT_STATUS.UNINITIALIZED
  }
}

function getChatWorkingProject({ owner_project_id, project_id }) {
  return $storex.projects.allProjectsById[project_id || owner_project_id] ||
            $storex.projects.activeProject
}

function getChatProject({ owner_project_id }) {
  return $storex.projects.allProjectsById[owner_project_id] ||
            $storex.projects.activeProject
}

function getRootChat(state, chatId) {
  let current = state.chats?.[chatId]
  if (!current) return null
  let depth = 0
  while (current?.parent_id && state.chats?.[current.parent_id] && depth < 20) {
    current = state.chats[current.parent_id]
    depth++
  }
  return current
}

export const getters = getterTree(state, {
  allChats: state => Object.values(state.chats || {}),
  allTags: state => new Set(Object.values(state.chats || {})?.map(c => c.tags).reduce((a, b) => a.concat(b), []) || []),
  allPRs: state => Object.values(state.chats || {}).filter(c => c.pr_view?.from_branch),
  isChatUpdating: state => (chatId) => {
    return (state.chatEvents[chatId]?.updatingCount || 0) > 0
  },
  activeChat: state => state.activeChatId ? (state.chats[state.activeChatId] || null) : null,
  chatProject: state => ({ project_id, owner_project_id }) => {
    return $storex.projects.allProjectsById[project_id || owner_project_id]
  },
  chatChildren: state => (chatId) => {
    const children = Object.values(state.chats || {}).filter(c => c.parent_id === chatId)
    return children
  },
  chatDescendants: (state, getters) => (chatId) => {
    const direct = getters.chatChildren(chatId)
    const indirect = direct.flatMap(child => getters.chatDescendants(child.id))
    return [...direct, ...indirect]
  },
  rootChat: state => (chatId) => getRootChat(state, chatId),
  searchResults: state => state.searchResults,
})

export const mutations = mutationTree(state, {
  setActiveChatId(state, chatId) {
    state.activeChatId = chatId || null
  },

  clearActiveChat(state) {
    state.activeChatId = null
  },

  setSearchResults(state, results) {
    state.searchResults = results
  },

  clearSearchResults(state) {
    state.searchResults = null
  },

  setChatUpdating(state, { chatId, updating }) {
    const current = state.chatEvents[chatId]?.updatingCount || 0
    const prevTimeoutId = state.chatEvents[chatId]?.timeoutId || null

    if (prevTimeoutId) {
      clearTimeout(prevTimeoutId)
    }

    if (!updating) {
      state.chatEvents = {
        ...state.chatEvents,
        [chatId]: {
          ...(state.chatEvents[chatId] || {}),
          updatingCount: 0,
          updatingAt: null,
          timeoutId: null,
        }
      }
    } else {
      const timeoutId = setTimeout(() => {
        $storex.chats.setChatUpdating({ chatId, updating: false })
      }, 10000)

      state.chatEvents = {
        ...state.chatEvents,
        [chatId]: {
          ...(state.chatEvents[chatId] || {}),
          updatingCount: current + 1,
          updatingAt: new Date().toISOString(),
          timeoutId,
        }
      }
    }
  },

  setChatStatus(state, { chatId, status }) {
    const chat = state.chats[chatId]
    if (!chat) return
    state.chats[chatId] = {
      ...chat,
      status
    }
  }
})

export const actions = actionTree(
  { state, getters, mutations },
  {
    async init ({ state }) {
    },
    async loadChats({ state }) {
      const chats = await $storex.api.chats.list()
      chats.forEach(chat => {
        if (chat.id && !state.chats[chat.id]) {
          registerChat(state, { ...chat, status: CHAT_STATUS.UNINITIALIZED })
        }
      })
    },
    async searchChats({ state }, options = {}) {
      let searchRequest

      if (options instanceof ChatSearchRequest) {
        searchRequest = options
      } else {
        if (!options.query || options.query.trim() === '') {
          $storex.chats.clearSearchResults()
          return null
        }
        searchRequest = new ChatSearchRequest(options)
      }

      const validationErrors = searchRequest.getValidationErrors()
      if (validationErrors.length > 0) {
        console.error('[chats store] Search validation failed:', validationErrors)
        return {
          error: validationErrors[0],
          results: [],
          total: 0,
          page: 1,
          page_size: searchRequest.page_size,
          total_pages: 0,
          has_next: false,
          has_prev: false,
        }
      }

      const project = $storex.projects.activeProject
      const results = await project.$api.chats.search(searchRequest)

      $storex.chats.setSearchResults(results)
      return results
    },
    async clearChatSearch() {
      $storex.chats.clearSearchResults()
    },
    async ensureChatRoot({ state }, chat) {
      if (!chat?.id) return null
      let current = state.chats[chat.id] || {
        id: chat.id,
        owner_project_id: chat.owner_project_id,
        project_id: chat.project_id
      }
      let depth = 0
      while (current?.parent_id && depth < 20) {
        const parent = state.chats[current.parent_id]
        if (!parent) {
          const loadedParent = await $storex.chats.loadChat({
            id: current.parent_id,
            owner_project_id: current.owner_project_id || current.project_id
          })
          if (!loadedParent) break
          current = loadedParent
        } else {
          current = parent
        }
        depth++
      }
      return getRootChat(state, current.id) || current
    },
    async loadChildrenHierarchy({ state, getters }, rootChat, maxDepth = 5) {
      if (!rootChat?.id) return []

      const loadRecursive = async (parentChat, depth = 0) => {
        if (depth >= maxDepth) return []
        const children = getters.chatChildren(parentChat.id) || []
        const result = [...children]
        for (const child of children) {
          result.push(...(await loadRecursive(child, depth + 1)))
        }
        return result
      }

      const descendants = await loadRecursive(rootChat)
      return [rootChat, ...descendants]
    },
    async loadUninitialized({ state }, chat) {
      if (!chat?.id) return null

      const storedChat = state.chats[chat.id]
      if (!storedChat) return null

      if (storedChat.status === CHAT_STATUS.LOADED) {
        return storedChat
      }

      if (storedChat.status === CHAT_STATUS.LOADING) {
        return storedChat
      }

      if (storedChat.status === CHAT_STATUS.UNINITIALIZED) {
        return await $storex.chats.loadChat(chat)
      }

      return storedChat
    },
    async saveChat({ state }, chat) {
      $storex.chats.setChatStatus({ chatId: chat.id, status: CHAT_STATUS.SAVING })
      try {
        const project = getChatProject(chat)
        await project.$api.chats.save(chat)
        await $storex.chats.loadChat(chat)
        $storex.chats.setChatStatus({ chatId: chat.id, status: CHAT_STATUS.LOADED })
      } catch (error) {
        $storex.chats.setChatStatus({ chatId: chat.id, status: CHAT_STATUS.LOADED })
      }
    },
    async saveChatInfo(_, chat) {
      $storex.chats.setChatStatus({ chatId: chat.id, status: CHAT_STATUS.SAVING })
      try {
        const project = getChatProject(chat)
        await project.$api.chats.saveChatInfo({ ...chat, messages: [] })
        await $storex.chats.loadChat(chat)
        $storex.chats.setChatStatus({ chatId: chat.id, status: CHAT_STATUS.LOADED })
      } catch (error) {
        $storex.chats.setChatStatus({ chatId: chat.id, status: CHAT_STATUS.LOADED })
      }
    },
    async findProjectChat({ state }, { id, owner_project_id }) {
      const project = $storex.projects.allProjectsById[owner_project_id]
      const chat = state.chats[id]
      if (chat) {
        return chat
      }
      const loadedChat = await project.$api.chats.loadChat({ id, owner_project_id })
      registerChat(state, loadedChat)
      return state.chats[id] || null
    },
    async loadChat({ state }, chat) {
      if (!state.chats[chat.id]) {
        const project = getChatProject(chat)
        $storex.chats.setChatStatus({ chatId: chat.id, status: CHAT_STATUS.LOADING })
        try {
          const loadedChat = await project.$api.chats.loadChat(chat)
          registerChat(state, loadedChat)
          $storex.chats.setChatStatus({ chatId: chat.id, status: CHAT_STATUS.LOADED })
        } catch (error) {
          $storex.chats.setChatStatus({ chatId: chat.id, status: CHAT_STATUS.UNINITIALIZED })
        }
      } else if (state.chats[chat.id].status === CHAT_STATUS.UNINITIALIZED) {
        const project = getChatProject(chat)
        $storex.chats.setChatStatus({ chatId: chat.id, status: CHAT_STATUS.LOADING })
        try {
          const loadedChat = await project.$api.chats.loadChat(chat)
          registerChat(state, loadedChat)
          $storex.chats.setChatStatus({ chatId: chat.id, status: CHAT_STATUS.LOADED })
        } catch (error) {
          $storex.chats.setChatStatus({ chatId: chat.id, status: CHAT_STATUS.UNINITIALIZED })
        }
      }
      return state.chats[chat.id]
    },
    async reloadChat({ state }, chat) {
      const project = getChatProject(chat)
      const freshChat = await project.$api.chats.loadChat(chat)
      if (freshChat && state.chats[chat.id]) {
        Object.assign(state.chats[chat.id], { ...freshChat, status: CHAT_STATUS.LOADED })
      } else {
        registerChat(state, { ...freshChat, status: CHAT_STATUS.LOADED })
      }
      return state.chats[chat.id]
    },
    async addMessage({ state }, { chat, message }) {
      if (!chat?.id) return

      const project = getChatProject(chat)

      if (!message.doc_id) {
        message.doc_id = uuidv4()
      }

      try {
        const updatedChat = await project.$api.chats.addMessage(chat.id, message)

        if (updatedChat && updatedChat.messages) {
          state.chats[chat.id].messages = updatedChat.messages
        }

        return updatedChat
      } catch (error) {
        console.error('[chats store] Failed to add message:', error)
        throw error
      }
    },
    async removeMessage({ state }, { chat, messageDocId }) {
      if (!chat?.id || !messageDocId) return

      const project = getChatProject(chat)

      try {
        const updatedChat = await project.$api.chats.removeMessage(chat.id, messageDocId)

        if (updatedChat && updatedChat.messages) {
          state.chats[chat.id].messages = updatedChat.messages
        }

        return updatedChat
      } catch (error) {
        console.error('[chats store] Failed to remove message:', error)
        throw error
      }
    },
    async updateMessage({ state }, { chat, messageDocId, fieldUpdates }) {
      if (!chat?.id || !messageDocId) return

      const project = getChatProject(chat)

      try {
        const updatedChat = await project.$api.chats.updateMessageField(chat.id, messageDocId, fieldUpdates)

        if (updatedChat && updatedChat.messages) {
          state.chats[chat.id].messages = updatedChat.messages
        } else if (updatedChat) {
          // If server doesn't return full chat, update local message directly
          const msg = state.chats[chat.id]?.messages?.find(m => m.doc_id === messageDocId)
          if (msg) Object.assign(msg, fieldUpdates)
        }

        return updatedChat
      } catch (error) {
        console.error('[chats store] Failed to update message:', error)
        throw error
      }
    },
    async updateMessages({ state }, { chat, messages }) {
      if (!chat?.id || !messages?.length) return

      const project = getChatProject(chat)

      try {
        // Batch update multiple message fields
        const promises = messages.map(({ doc_id, ...updates }) => 
          project.$api.chats.updateMessageField(chat.id, doc_id, updates)
        )

        const results = await Promise.all(promises)

        // Use first result or reload chat if needed
        if (results[0] && results[0].messages) {
          state.chats[chat.id].messages = results[0].messages
        } else {
          await $storex.chats.reloadChat(chat)
        }

        return results
      } catch (error) {
        console.error('[chats store] Failed to update messages:', error)
        throw error
      }
    },
    async updateChatInfo({ state }, { chat, updates }) {
      if (!chat?.id) return

      const project = getChatProject(chat)

      try {
        // Update only metadata/info, not messages
        const updatedChat = await project.$api.chats.updateMetadata(chat.id, updates)

        if (updatedChat && state.chats[chat.id]) {
          Object.assign(state.chats[chat.id], updates)
        }

        return updatedChat
      } catch (error) {
        console.error('[chats store] Failed to update chat info:', error)
        throw error
      }
    },
    async deleteChat({ state, getters }, chat) {
      if (!chat?.id) return

      const descendants = getters.chatDescendants(chat.id) || []

      if (!chat.temp) {
        const project = getChatProject(chat)
        await project.$api.chats.delete(chat)
      }

      const ids = new Set([chat.id, ...(descendants || []).map(c => c.id)])
      ids.forEach(id => {
        delete state.chats[id]
      })

      if (ids.has(state.activeChatId)) {
        $storex.chats.clearActiveChat()
      }
    },
    async setActiveChat({ state }, activeChat) {
      const { id, project_id, owner_project_id } = activeChat || {}

      if (!id) {
        $storex.chats.clearActiveChat()
        return
      }

      await $storex.chats.reloadChat({ id, project_id, owner_project_id })

      $storex.chats.setActiveChatId(id)

      if (!$storex.ui.isMobile && $storex.ui.viewMode !== 'vibe') {
        $storex.ui.openChat($storex.chats.activeChat)
      }
    },
    async createNewChat({ state }, chat) {
      chat = {
        id: uuidv4(),
        mode: 'chat',
        profiles: [],
        chat_index: 0,
        messages: [],
        auto_initialize: !chat.name,
        owner_project_id: chat.owner_project_id || $storex.projects.activeProject.project_id,
        status: CHAT_STATUS.UNINITIALIZED,
        ...chat
      }
      registerChat(state, chat)
      if (!chat.temp) {
        await $storex.chats.saveChat(chat)
      }
      return state.chats[chat.id]
    },
    async createNewChatWithProject({ state }, { project, chat = {} }) {
      const chatData = {
        ...chat,
        owner_project_id: project?.project_id || $storex.projects.activeProject.project_id
      }
      return await $storex.chats.createNewChat(chatData)
    },
    async createNewChatFromUrl({ state }, chat) {
      chat = {
        id: uuidv4(),
        mode: 'chat',
        profiles: [],
        chat_index: 0,
        status: CHAT_STATUS.UNINITIALIZED,
        ...chat
      }
      const project = getChatProject(chat)
      const savedChat = await project.$api.chats.fromUrl(chat)
      registerChat(state, { ...savedChat, status: CHAT_STATUS.LOADED })
      if (!chat.temp) {
        await $storex.chats.setActiveChat(savedChat)
      }
      return state.chats[savedChat?.id]
    },
    async createNewBoardChat({ state }, { boardTitle, columnTitle, chat }) {
      boardTitle = boardTitle || chat.board
      columnTitle = columnTitle || chat.column
      const newColumn = {
        title: columnTitle,
        chats: []
      }
      if (!$storex.projects.kanban) {
        await $storex.projects.loadKanban()
      }
      if (!$storex.projects.kanban.boards[boardTitle]) {
        $storex.projects.kanban.boards = {
          ...$storex.projects.kanban.boards,
          [boardTitle]: {
            columns: [newColumn]
          }
        }
      }
      let column = $storex.projects.allBoards
                        .find(({ title }) => title === boardTitle).columns.find(({ title }) => title === columnTitle)
      if (!column) {
        column = newColumn
        $storex.projects.kanban.boards[boardTitle].columns.push(column)
      }

      const newChat = await $storex.chats.createNewChat({
        board: boardTitle,
        column: columnTitle,
        ...chat
      })
      await $storex.chats.setActiveChat(newChat)
      column.chats = [...column?.chats || [], newChat.id]
      $storex.projects.saveKanban($storex.projects.kanban)
      return newChat
    },
    async createNewThread(_, { chat, mode, message }) {
      const { files, profiles, doc_id: subtaskMessageId } = message
      const findChild = $storex.chats.allChats.find(c => c.message_id === subtaskMessageId)

      if (!findChild) {
        const boardTitle = chat.board
        const columnTitle = chat.column
        await $storex.chats.createNewBoardChat({
          boardTitle, columnTitle,
          chat: {
            parent: chat,
            name: `${subtaskMessageId} - thread`,
            project_id: chat.project_id,
            parent_id: chat.parent_id,
            message_id: subtaskMessageId,
            file_list: files,
            profiles: profiles,
            mode,
            board: chat.board,
            column: chat.column,
            activateChat: true,
            messages: [{ ...message, doc_id: null }]
          }
        })
      } else {
        await $storex.chats.setActiveChat(findChild)
      }
    },
    async onChatEvent({ state }, { event, data }) {
      const {
        chat: {
          id: chatId,
          owner_project_id
        },
        message,
        event_type,
        type,
        codx_path
      } = data

      if (event_type === 'error') {
        $storex.ui.addNotification({ text: message, type: event_type })
      }

      if (chatId) {
        if (type === 'changed' || !state.chats[chatId]) {
          await $storex.chats.reloadChat({ id: chatId, owner_project_id })
        }
        const chat = state.chats[chatId]
        if (chat && message) {
          const allMessagesDone = chat.messages.every(m => m.done)
          if (allMessagesDone) {
            $storex.chats.setChatUpdating({ chatId, updating: false })
          } else {
            $storex.chats.setChatUpdating({ chatId, updating: true })
          }
        }
      }
    },
    async readFile({ state }, { chat, file }) {
      const project = getChatWorkingProject(chat)
      return project.$api.files.read(file)
    },
    async writeFile({ state }, { chat, file, content }) {
      const project = getChatWorkingProject(chat)
      return project.$api.files.write(file, content)
    }
  }
)
